STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'


class Hangman:
    def __init__(self, word):
        if not isinstance(word, str):
            raise ValueError("word must be a string")
        self.word = word
        self.remaining_guesses = 10
        self.status = STATUS_ONGOING
        self._guessed = set()

    def guess(self, char):
