            return  # ignore invalid guesses silently
        ch = char[0].lower()

        # set of alphabetic characters in the word (lowercased)
        word_chars = {c.lower() for c in self.word if c.isalpha()}

        # If already guessed, count as a wrong guess (decrement remaining guesses)
        if ch in self._guessed:
            self.remaining_guesses -= 1
        else:
            self._guessed.add(ch)
            if ch not in word_chars:
                self.remaining_guesses -= 1

        # Update status: win takes precedence over loss
        if word_chars and word_chars.issubset(self._guessed):
            self.status = STATUS_WIN
        elif self.remaining_guesses <= 0:
            self.status = STATUS_LOSE
        else:
            self.status = STATUS_ONGOING

    def get_masked_word(self):
        masked = []
        for c in self.word:
            if not c.isalpha() or c.lower() in self._guessed:
                masked.append(c)
            else:
                masked.append('_')
        return ''.join(masked)

    def get_status(self):
        return self.status
